import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Inspect12{public static void main(String[]args)throws Exception{int n=0;for(String path:args)try(var jar=new ZipFile(path)){for(var entry:Collections.list(jar.entries()))if(entry.getName().endsWith(".class")&&(entry.getName().contains("/perf12/")||entry.getName().contains("/hybrid/Vision")||entry.getName().contains("/hybrid/Gpu12")||entry.getName().contains("/hybrid/VR12"))){ClassNode c=new ClassNode();new ClassReader(jar.getInputStream(entry).readAllBytes()).accept(c,0);for(var m:c.methods)if((m.access&(Opcodes.ACC_NATIVE|Opcodes.ACC_ABSTRACT))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);n++;}}System.out.println("NEW_RENDER_CLASSES_BYTECODE_CHECKS="+n);}}
